import java.lang.annotation.*;
import java.lang.reflect.Method;

public class CustomAnnotationsDemo {
    @Documented
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.METHOD)
    @interface Todo {
        String value();
        String author() default "unknown";
    }

    @Inherited
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.TYPE)
    @interface AuditableEntity {
        String system();
    }

    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.METHOD)
    @interface Schedules {
        Schedule[] value();
    }

    @Repeatable(Schedules.class)
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.METHOD)
    @interface Schedule {
        String day();
    }

    @AuditableEntity(system = "demo")
    static class BaseEntity {}
    static class SubEntity extends BaseEntity {} // BEZ wlasnej adnotacji

    static class TaskExample {
        @Todo("dodac walidacje")
        public void parse() {}

        @Schedule(day = "poniedzialek")
        @Schedule(day = "sroda")
        public void weeklySync() {}
    }

    public static void main(String[] args) throws Exception {
        Method parse = TaskExample.class.getDeclaredMethod("parse");
        Todo todo = parse.getAnnotation(Todo.class);
        System.out.println(todo.value() + " (" + todo.author() + ")");

        System.out.println(SubEntity.class.getAnnotation(AuditableEntity.class)); // dziedziczone!

        Method sync = TaskExample.class.getDeclaredMethod("weeklySync");
        for (Schedule s : sync.getAnnotationsByType(Schedule.class)) {
            System.out.println(s.day());
        }
    }
}
