class RegistrationForm {
    @NotBlank
    String email;
    @Range(min = 18, max = 120)
    int age;
    RegistrationForm(String email, int age) { this.email = email; this.age = age; }
}

static List<String> validate(Object obj) throws Exception {
    List<String> errors = new ArrayList<>();
    for (Field field : obj.getClass().getDeclaredFields()) {
        field.setAccessible(true);
        if (field.isAnnotationPresent(NotBlank.class)) {
            String value = (String) field.get(obj);
            if (value == null || value.isBlank()) errors.add(field.getName() + " nie moze byc puste");
        }
        if (field.isAnnotationPresent(Range.class)) {
            Range r = field.getAnnotation(Range.class);
            int value = field.getInt(obj);
            if (value < r.min() || value > r.max()) errors.add(field.getName() + " poza zakresem");
        }
    }
    return errors;
}

System.out.println(validate(new RegistrationForm("a@b.com", 25))); // []
System.out.println(validate(new RegistrationForm("", 10))); // 2 bledy

