@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface MiniTest {}

class MathTests {
    @MiniTest
    void testAddition() { if (2 + 2 != 4) throw new AssertionError("zle dodawanie"); }
    @MiniTest
    void testSubtraction() { if (5 - 3 != 2) throw new AssertionError("zle odejmowanie"); }
    @MiniTest
    void testFailing() { if (1 + 1 != 3) throw new AssertionError("celowa porazka"); }
}

int passed = 0, failed = 0;
for (Method m : MathTests.class.getDeclaredMethods()) {
    if (m.isAnnotationPresent(MiniTest.class)) {
        try {
            m.invoke(new MathTests());
            passed++;
            System.out.println(m.getName() + ": PASSED");
        } catch (Exception e) {
            failed++;
            System.out.println(m.getName() + ": FAILED (" + e.getCause().getMessage() + ")");
        }
    }
}
System.out.println("PASSED: " + passed + ", FAILED: " + failed);

