@Documented
@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@interface ConfigProperty {
    String key();
    String defaultValue() default "";
}

@Inherited
@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.TYPE)
@interface ConfigSource {
    String file();
}

@ConfigSource(file = "app.properties")
class AppConfig {
    @ConfigProperty(key = "app.name", defaultValue = "JavaQuest")
    String name;
    @ConfigProperty(key = "app.port", defaultValue = "8080")
    String port;
}

class ExtendedAppConfig extends AppConfig {
    @ConfigProperty(key = "app.extra")
    String extra;
}

static void dump(Class<?> type) {
    ConfigSource source = type.getAnnotation(ConfigSource.class);
    System.out.println(type.getSimpleName() + " (zrodlo: " + source.file() + "):");
    for (Field field : type.getDeclaredFields()) {
        ConfigProperty cp = field.getAnnotation(ConfigProperty.class);
        if (cp != null) {
            System.out.println("  " + cp.key() + " = " + cp.defaultValue());
        }
    }
}

dump(AppConfig.class);
dump(ExtendedAppConfig.class); // dziedziczy @ConfigSource z AppConfig
